  "editing-cell": "// <EditingExample mode=\"cell\" />\nfunction EditingExample({ mode }: { mode: EditDisplayMode }) {\n  const [data, setData] = React.useState(() => makeUsers(12))\n  const columns = useUserColumns()\n  const table = useDataTable({\n    data,\n    columns,\n    getRowId: (row) => row.id,\n    enableEditing: true,\n    editDisplayMode: mode,\n    enablePagination: false,\n    createRowDefaults: {\n      firstName: \"\",\n      lastName: \"\",\n      email: \"\",\n      role: \"Viewer\",\n      department: \"Engineering\",\n      status: \"pending\",\n      age: 30,\n      salary: 50000,\n    },\n    onEditingCellSave: ({ row, column, value }) =>\n      setData((prev) =>\n        prev.map((r) =>\n          r.id === row.id ? ({ ...r, [column.id]: value } as User) : r\n        )\n      ),\n    onEditingRowSave: ({ row, values, exit }) => {\n      setData((prev) =>\n        prev.map((r) =>\n          r.id === row.id ? { ...r, ...(values as Partial<User>) } : r\n        )\n      )\n      exit()\n    },\n    onCreatingRowSave: ({ values, exit }) => {\n      setData((prev) => [\n        {\n          ...makeUsers(1)[0]!,\n          id: `U-${2000 + prev.length}`,\n          ...(values as Partial<User>),\n        },\n        ...prev,\n      ])\n      exit()\n    },\n    renderTopToolbarCustomActions: ({ table }) => (\n      <Button variant=\"outline\" size=\"sm\" onClick={() => table.beginCreate()}>\n        <RiAddLine />\n        New\n      </Button>\n    ),\n  })\n  return <DataTable table={table} />\n}",
  "editing-row": "// <EditingExample mode=\"row\" />\nfunction EditingExample({ mode }: { mode: EditDisplayMode }) {\n  const [data, setData] = React.useState(() => makeUsers(12))\n  const columns = useUserColumns()\n  const table = useDataTable({\n    data,\n    columns,\n    getRowId: (row) => row.id,\n    enableEditing: true,\n    editDisplayMode: mode,\n    enablePagination: false,\n    createRowDefaults: {\n      firstName: \"\",\n      lastName: \"\",\n      email: \"\",\n      role: \"Viewer\",\n      department: \"Engineering\",\n      status: \"pending\",\n      age: 30,\n      salary: 50000,\n    },\n    onEditingCellSave: ({ row, column, value }) =>\n      setData((prev) =>\n        prev.map((r) =>\n          r.id === row.id ? ({ ...r, [column.id]: value } as User) : r\n        )\n      ),\n    onEditingRowSave: ({ row, values, exit }) => {\n      setData((prev) =>\n        prev.map((r) =>\n          r.id === row.id ? { ...r, ...(values as Partial<User>) } : r\n        )\n      )\n      exit()\n    },\n    onCreatingRowSave: ({ values, exit }) => {\n      setData((prev) => [\n        {\n          ...makeUsers(1)[0]!,\n          id: `U-${2000 + prev.length}`,\n          ...(values as Partial<User>),\n        },\n        ...prev,\n      ])\n      exit()\n    },\n    renderTopToolbarCustomActions: ({ table }) => (\n      <Button variant=\"outline\" size=\"sm\" onClick={() => table.beginCreate()}>\n        <RiAddLine />\n        New\n      </Button>\n    ),\n  })\n  return <DataTable table={table} />\n}",
